ORIGINALS={'class_creation.resolve_bases': 'def resolve_bases(evaluator, bases):\n    """High-level, one-layer native adaptation; low-level allocation stays strict."""\n    from .objects import ChaosClass\n    from .language import LanguageError, TupleValue\n    if type(bases) is not list or len(bases)>32:\n        raise LanguageError(\'类基类需要至多 32 项 List\', code=\'argument_error\')\n    for index, base in enumerate(bases): preflight_base(evaluator, base, bases[:index])\n    original = TupleValue(bases); resolved=[]; changed=False\n    for base in bases:\n        if type(base) is ChaosClass: resolved.append(base)\n        else:\n            changed=True\n            function=yield from evaluator._s_default_get_member(base,\'__mro_entries__\')\n            entries=yield from evaluator._s_invoke(function,[original],synchronous=True)\n            if type(entries) is not TupleValue:\n                raise LanguageError(\'__mro_entries__ 必须同步返回 Class 的 Tuple\', code=\'argument_error\')\n            validate_value(evaluator, entries)\n            if any(type(item) is not ChaosClass or item.building for item in entries):\n                raise LanguageError(\'__mro_entries__ 只展开一层已完成的 Class\', code=\'argument_error\')\n            resolved.extend(entries)\n        if len(resolved)>32: raise LanguageError(\'展开后的基类需要至多 32 项\', code=\'argument_error\')\n    linear=validate_bases(evaluator,resolved)\n    return resolved, original if changed else None, linear', 'class_creation.finalize': 'def finalize(evaluator, klass, options):\n    from .agent_tools import scope\n    with scope(evaluator, klass.capabilities):\n        return (yield from _finalize(evaluator, klass, options))', 'class_creation._finalize': "def _finalize(evaluator, klass, options):\n    from .objects import descriptor_protocols, ProtocolCall, member_value, declaration, bind_member\n    from .language import LanguageError, check_type\n    klass.building = False\n    notifications = [(label, member_value(member)) for label, member in klass.members.items()]\n    for label, value in notifications:\n        evaluator.tick()\n        if '__set_name__' in descriptor_protocols(value):\n            yield from evaluator._s_access_result(ProtocolCall(value, '__set_name__', [klass, label], True))\n    inherited = declaration(klass, '__init_subclass__', after=klass)\n    if inherited is None:\n        if options: raise LanguageError('终端 __init_subclass__ 不接受类 options', code='argument_error')\n    else:\n        hook = yield from evaluator._s_access_result(bind_member(member_value(inherited), inherited, klass, klass, evaluator))\n        result = yield from evaluator._s_invoke(hook, [], options, synchronous=True)\n        check_type(result, 'Null')\n    return klass", 'class_creation.create': 'def create(evaluator, request):\n    from .metaclasses import create as metaclass_create\n    return (yield from metaclass_create(evaluator, request))', 'class_creation.construct': "def construct(evaluator, klass, args, kwargs, span):\n    from .objects import ChaosInstance, ClassMethod, declaration, member_value, owned, bind_member\n    from .language import LanguageError, Function, Native, check_type\n    from .suspension import Task, Generator\n    if klass.building: raise LanguageError('类尚未完成定义')\n    creator = declaration(klass, '__new__')\n    if creator is None: value = allocate(evaluator, klass)\n    else:\n        function = yield from evaluator._s_default_get_member(klass, '__new__')\n        supplied = list(args) if isinstance(member_value(creator), ClassMethod) else [klass] + list(args)\n        value = yield from evaluator._s_invoke(function, supplied, kwargs, span=span, synchronous=True)\n        if isinstance(value, (Task, Generator)):\n            raise LanguageError('__new__ 不能返回 Task 或 Generator', code='argument_error')\n        validate_value(evaluator, value)\n    if isinstance(value, ChaosInstance) and any(base is klass for base in value.klass.mro):\n        owned(value.klass, evaluator)\n        initializer = declaration(value.klass, '__init__')\n        if initializer is None:\n            if creator is None and (args or kwargs): raise LanguageError(klass.name+' 构造不接受参数', code='argument_error')\n        else:\n            if not initializer.method or not (type(initializer.value) is Native or type(initializer.value) is Function and initializer.value.flavor == 'fn'):\n                raise LanguageError('__init__ 必须是同步 fn 或原生方法')\n            result = yield from evaluator._s_invoke((yield from evaluator._s_default_get_member(value, '__init__')), args, kwargs, span=span, synchronous=True)\n            check_type(result, 'Null')\n    return project_value(evaluator, value, klass, value.klass if type(value) is ChaosInstance else klass) if creator is not None else value", 'metaclasses.check': 'def check(evaluator, request):\n    """Public predicates use the actual metaclass, never the class namespace."""\n    from .objects import ChaosClass, owned, declaration, member_value, bind_member\n    from .language import LanguageError, check_type\n    from .class_creation import validate_value\n    from .agent_tools import scope\n    klass = request.klass\n    if type(klass) is not ChaosClass or klass.building:\n        raise LanguageError(\'类型判断需要已完成的 Class\', code=\'argument_error\')\n    validate_value(evaluator, klass); validate_value(evaluator, request.value)\n    if request.operation == \'subclass\' and (type(request.value) is not ChaosClass or request.value.building):\n        raise LanguageError(\'issubclass 的 child 需要已完成的 Class\', code=\'argument_error\')\n    meta = owned(klass.metaclass, evaluator)\n    name = \'__instancecheck__\' if request.operation == \'instance\' else \'__subclasscheck__\'\n    member = declaration(meta, name)\n    if member is None: raise LanguageError(\'元类缺少 \'+name, code=\'argument_error\')\n    with scope(evaluator, klass.capabilities), scope(evaluator, meta.capabilities):\n        function = yield from evaluator._s_access_result(bind_member(member_value(member), member, klass, meta, evaluator, instance_access=True))\n        result = yield from evaluator._s_invoke(function, [request.value], synchronous=True)\n        return check_type(result, \'Bool\')', 'metaclasses.mapping_member': "def mapping_member(evaluator, namespace, name):\n    from .objects import declaration, special_method\n    from .language import LanguageError\n    if declaration(namespace.klass, name) is None:\n        raise LanguageError('准备命名空间缺少 '+name, code='argument_error')\n    return (yield from evaluator._s_access_result(special_method(namespace, name, evaluator)))", 'metaclasses.namespace_snapshot': "def namespace_snapshot(evaluator, namespace):\n    from .objects import ChaosInstance, owned\n    from .language import LanguageError, ResourceLimit\n    from .class_creation import validate_value\n    validate_value(evaluator, namespace)\n    if type(namespace) is dict:\n        if len(namespace)>10000 or any(type(k) is not str for k in namespace):\n            raise LanguageError('命名空间需要至多 10000 个 String 键', code='argument_error')\n        return dict(namespace)\n    if type(namespace) is not ChaosInstance:\n        raise LanguageError('__prepare__ 需要 Record 或原生命名空间映射 Instance', code='argument_error')\n    owned(namespace.klass, evaluator)\n    keys = yield from evaluator._s_invoke((yield from evaluator._s_get_member(namespace, 'keys')), [], synchronous=True)\n    if type(keys) is not list or len(keys)>10000 or any(type(k) is not str for k in keys) or len(set(keys))!=len(keys):\n        raise LanguageError('命名空间 keys 必须是至多 10000 个唯一 String 的 List', code='argument_error')\n    validate_value(evaluator, keys)\n    result = {}; getter = yield from mapping_member(evaluator, namespace, '__getitem__')\n    for key in keys:\n        evaluator.tick(); value = yield from evaluator._s_invoke(getter, [key], synchronous=True)\n        validate_result(evaluator, value); result[key] = value\n    validate_value(evaluator, result)\n    return result", 'metaclasses.namespace_read': "def namespace_read(evaluator, namespace, key):\n    from .language import LanguageError\n    from .objects import ClassMember\n    from .class_creation import project_field, validate_value\n    if type(namespace) is dict:\n        if key not in namespace: return False, None\n        value = namespace[key]\n    else:\n        getter = yield from mapping_member(evaluator, namespace, '__getitem__')\n        try: value = yield from evaluator._s_invoke(getter, [key], synchronous=True)\n        except LanguageError as error:\n            if error.code not in ('KeyError', 'key_error'): raise\n            return False, None\n    validate_result(evaluator, value)\n    return True, project_field(evaluator,value,'value') if type(value) is ClassMember else value", 'metaclasses.lookup_name': "def lookup_name(evaluator, env, name):\n    from .language import Cell, LanguageError\n    current = env\n    while current is not None:\n        namespace = getattr(current, '_prepared_namespace', None)\n        if namespace is not None and name != getattr(current, '_class_name', None):\n            found, value = yield from namespace_read(evaluator, namespace, name)\n            if found: return value\n            # A deleted/missing class local is not resurrected from the cache.\n        elif name in current.values:\n            value=current.values[name]\n            return value.value if isinstance(value,Cell) else value\n        current=current.parent\n    raise LanguageError('未定义名称 '+name)", 'metaclasses.assign_name': "def assign_name(evaluator, env, name, value):\n    from .language import Cell, LanguageError, check_type\n    from .objects import ClassMember\n    from .class_creation import member_value\n    current=env\n    while current is not None and name not in current.values: current=current.parent\n    if current is None or not hasattr(current,'_prepared_namespace'): return env.assign(name,value)\n    cell=current.values[name]\n    if not isinstance(cell,Cell) or getattr(cell,'_class_reference',False): raise LanguageError('不可赋值给 let/函数绑定 '+name,code='argument_error')\n    value=check_type(value,cell.contract)\n    item=member_value(evaluator,value,mutable=True,contract=cell.contract)\n    effective=yield from namespace_write(evaluator,current._prepared_namespace,name,item)\n    cell.value=effective.value if type(effective) is ClassMember else effective\n    return cell.value", 'metaclasses.namespace_write': "def namespace_write(evaluator, namespace, key, value):\n    from .language import LanguageError, ResourceLimit, check_type\n    from .class_creation import validate_value\n    validate_value(evaluator, value)\n    if type(namespace) is dict:\n        if key not in namespace and len(namespace)>=10000: raise ResourceLimit('类成员超过 10000 项')\n        namespace[key]=value\n        return value\n    setter = yield from mapping_member(evaluator, namespace, '__setitem__')\n    result = yield from evaluator._s_invoke(setter, [key,value], synchronous=True)\n    check_type(result, 'Null')\n    getter = yield from mapping_member(evaluator, namespace, '__getitem__')\n    result = yield from evaluator._s_invoke(getter, [key], synchronous=True)\n    return validate_result(evaluator, result)", 'metaclasses.original_bases_write': 'def original_bases_write(evaluator, namespace, original, *sources):\n    """Automatic reflection cannot retain a wider live proxy in a narrow class."""\n    from .class_creation import project_value\n    original = project_value(evaluator, original, namespace, *sources)\n    return (yield from namespace_write(evaluator, namespace, \'__orig_bases__\', original))', 'metaclasses.prepare': "def prepare(evaluator, meta, name, bases, options):\n    from .objects import ChaosInstance, ChaosClass\n    from .language import LanguageError\n    function = None\n    if type(meta) in (ChaosClass, ChaosInstance):\n        try: function = yield from evaluator._s_default_get_member(meta, '__prepare__')\n        except LanguageError as error:\n            if error.code != 'attribute_error': raise\n    value = {} if function is None else (yield from evaluator._s_invoke(function, [name,list(bases)], options, synchronous=True))\n    validate_result(evaluator, value)\n    snapshot = yield from namespace_snapshot(evaluator, value)\n    # Record retains value semantics; only the internal copy receives writes.\n    return (dict(snapshot) if type(value) is dict else value), snapshot", 'metaclasses.lowlevel_new': "def lowlevel_new(evaluator, request):\n    from .class_creation import validate_bases, validate_options, validate_name, shell, install, finalize, member_value, project_value\n    from .objects import ClassMember, ChaosClass\n    from .language import LanguageError, Cell\n    if not is_metaclass(evaluator, request.metaclass):\n        raise LanguageError('Type.__new__ mcls 需要原生 Type 子类', code='argument_error')\n    linear = validate_bases(evaluator, request.bases)\n    options = validate_options(evaluator, request.options)\n    if 'metaclass' in options: raise LanguageError('Type.__new__ options 不接受 metaclass', code='argument_error')\n    validate_name(request.name)\n    selected = select(evaluator, request.bases, request.metaclass)\n    if selected is not request.metaclass:\n        return (yield from new_value(evaluator, selected, [request.name, request.bases, request.namespace], options))\n    members = yield from namespace_snapshot(evaluator, request.namespace)\n    validated = []\n    for label, value in members.items():\n        evaluator.tick(); label.encode('utf-8')\n        if type(value) is ClassMember:\n            item=member_value(evaluator,value.value,mutable=value.mutable,method=value.method,contract=value.contract)\n            validated.append((label,item.value,item.contract,item.mutable,item.method,value.capabilities))\n        else: validated.append((label,value,'Any',False,False,None))\n    klass = None\n    previous_members = {}\n    for pending in reversed(build_stack(evaluator)):\n        shell_value=pending['shell']\n        if not pending['used'] and shell_value.name==request.name and shell_value.bases==tuple(request.bases) and shell_value.metaclass is selected:\n            klass=shell_value;pending['used']=True\n            previous_members=klass.members;klass.members={};break\n    if klass is None: klass = shell(evaluator, request.name, request.bases, linear, metaclass=selected)\n    captured=getattr(request.namespace,'capabilities',None)\n    if captured is not None: klass.capabilities=captured if klass.capabilities is None else klass.capabilities & captured\n    for args in validated:\n        install(evaluator,klass,*args)\n        previous=previous_members.get(args[0]);current=klass.members[args[0]]\n        if current.mutable and previous is not None and previous.mutable and type(previous.value) is Cell:\n            # Source closures and the published mutable member retain one cell.\n            # A metaclass may change its effective value and contract first.\n            previous.value.value=current.value.value\n            previous.value.contract=current.value.contract\n            current.value=previous.value\n    return (yield from finalize(evaluator,klass,options))", 'metaclasses.new_value': "def new_value(evaluator, meta, args, options):\n    from .objects import ClassMethod, declaration, member_value, bind_member\n    member=declaration(meta,'__new__')\n    if member_value(member) is member_value(evaluator.native_type.members['__new__']):\n        function = yield from evaluator._s_access_result(bind_member(member_value(member), member, None, meta, evaluator))\n    else: function = yield from evaluator._s_default_get_member(meta, '__new__')\n    supplied=list(args) if member is not None and isinstance(member_value(member),ClassMethod) else [meta]+list(args)\n    return validate_result(evaluator,(yield from evaluator._s_invoke(function,supplied,options,synchronous=True)))", 'metaclasses.default_call': "def default_call(evaluator, request):\n    from .objects import ChaosClass, ChaosInstance, owned, declaration, bind_member, member_value\n    from .class_creation import construct, project_value\n    from .language import LanguageError, check_type\n    klass,args,options=request.klass,request.args,request.options\n    owned(klass,evaluator)\n    if not is_metaclass(evaluator,klass):\n        return (yield from construct(evaluator,klass,args,options,evaluator.current_span))\n    if klass is evaluator.native_type and len(args)==1 and not options:\n        value=args[0];owned(value,evaluator)\n        if type(value) is ChaosClass: result=value.metaclass\n        elif type(value) is ChaosInstance: result=value.klass\n        else: raise LanguageError('Type(value) 目前查询 Class 或 Instance；内建标量类型身份尚未实现',code='argument_error')\n        return project_value(evaluator,result,value)\n    value=yield from new_value(evaluator,klass,args,options)\n    if type(value) is ChaosClass and subclass(value.metaclass,klass):\n        initializer=declaration(value.metaclass,'__init__')\n        if initializer is not None:\n            function=yield from evaluator._s_access_result(bind_member(member_value(initializer),initializer,value,value.metaclass,evaluator,instance_access=True))\n            result=yield from evaluator._s_invoke(function,args,options,synchronous=True)\n            check_type(result,'Null')\n    return project_value(evaluator,value,klass,value.metaclass if type(value) is ChaosClass else klass)", 'metaclasses.class_call': "def class_call(evaluator, klass, args, options, span=None, synchronous=False):\n    from .objects import declaration, bind_member, member_value, owned\n    from .language import LanguageError\n    if klass.building: raise LanguageError('类尚未完成定义',code='argument_error')\n    meta=owned(klass.metaclass,evaluator)\n    member=declaration(meta,'__call__')\n    if member is None: raise LanguageError('元类缺少 __call__',code='argument_error')\n    function=yield from evaluator._s_access_result(bind_member(member_value(member),member,klass,meta,evaluator,instance_access=True))\n    return (yield from evaluator._s_invoke(function,args,options,span=span,synchronous=synchronous))", 'metaclasses.create': "def create(evaluator, request):\n    from .class_creation import resolve_bases, validate_options, validate_name, validate_value, project_value\n    from .agent_tools import scope\n    from .language import LanguageError, ResourceLimit\n    validate_name(request.name)\n    bases, original, _ = yield from resolve_bases(evaluator, request.bases)\n    options=validate_options(evaluator,request.options)\n    explicit=options.pop('metaclass',DEFAULT);meta=select(evaluator,bases,explicit)\n    if type(request.members) is not dict or len(request.members)>10000 or any(type(k) is not str for k in request.members):\n        raise LanguageError('类 members 需要至多 10000 个 String 键 Record',code='argument_error')\n    validate_value(evaluator,request.members)\n    with scope(evaluator,getattr(meta,'capabilities',None)):\n        namespace,_=yield from prepare(evaluator,meta,request.name,bases,options)\n        for label,value in request.members.items():\n            yield from namespace_write(evaluator,namespace,label,value)\n        if original is not None: yield from original_bases_write(evaluator,namespace,original,meta)\n        result=yield from evaluator._s_invoke(meta,[request.name,list(bases),namespace],options,synchronous=True)\n        validate_result(evaluator,result)\n        if original is not None: original_bases_result(evaluator,result)\n        return project_value(evaluator,result,meta,namespace)", 'language._s_decorated': "def _s_decorated(self, node, env, method_closure=None):\n        decorators = []\n        for expression in node[1]: decorators.append((yield from self._s_evaluate(expression, env)))\n        declaration = node[2]\n        if declaration[0] == 'def':\n            value = yield from self._s_evaluate(declaration[2], env)\n            if method_closure is None: value.env.values[declaration[1]] = value\n            else: value.env = method_closure.snapshot()\n        elif declaration[0] == 'class':\n            value = yield from self._s_class(declaration, env, publish=False)\n        else:\n            value = Agent(declaration[1], (yield from self._s_evaluate(declaration[2], env)), self)\n        for decorator in reversed(decorators): value = yield from self._s_invoke(decorator, [value])\n        return value", 'language._s_class': "def _s_class(self, node, env, publish=True):\n        from .objects import ChaosClass, Member, Property, member_value, property_update, c3_merge, owned\n        from .class_creation import class_options, validate_options, validate_name, shell, install, member_value as create_member, preflight_base, resolve_bases\n        from .metaclasses import DEFAULT, select, prepare, namespace_write, build_stack, validate_result, is_metaclass, original_bases_write, original_bases_result\n        from .agent_tools import scope as authority_scope\n        name, declarations = node[1], node[3][1]\n        if name in env.values: raise LanguageError('不可重复绑定 '+name)\n        if len(node[2]) > 32 or len(declarations) > 10000: raise ResourceLimit('类基类或成员数量超过限制')\n        declared = set()\n        for member in declarations:\n            label = member[2][1] if member[0] == 'decorated' else member[1]\n            if label in declared and member[0] != 'decorated': raise LanguageError('类成员不能重名')\n            declared.add(label)\n        bases = []\n        for expression in node[2]:\n            base = yield from self._s_evaluate(expression, env)\n            preflight_base(self, base, bases)\n            bases.append(base)\n        bases, original_bases, linear = yield from resolve_bases(self, bases)\n        options = {}\n        for argument in class_options(node):\n            if argument[0] == 'keyword':\n                value = yield from self._s_evaluate(argument[2], env)\n                if argument[1] in options: raise LanguageError('重复类选项 '+argument[1], code='argument_error')\n                options[argument[1]] = value\n            elif argument[0] == 'kwspread':\n                values = yield from self._s_evaluate(argument[1], env)\n                if type(values) is not dict or any(type(key) is not str for key in values):\n                    raise LanguageError('类 ** 选项需要 String 键 Record', code='argument_error')\n                if options.keys() & values.keys(): raise LanguageError('重复展开类选项', code='argument_error')\n                if len(options) + len(values) > 10000: raise ResourceLimit('类选项超过 10000 项')\n                options.update(values)\n            else: raise LanguageError('类选项只支持具名参数和 ** 展开', code='argument_error')\n        options = validate_options(self, options)\n        validate_name(name)\n        explicit = options.pop('metaclass', DEFAULT)\n        meta = select(self, bases, explicit)\n        with authority_scope(self, getattr(meta, 'capabilities', None)):\n            namespace, seeded = yield from prepare(self, meta, name, bases, options)\n            klass = shell(self, name, bases, linear, metaclass=meta if is_metaclass(self, meta) else self.native_type)\n            cell = Cell(klass, 'Any'); cell._class_reference = True\n            local = Env(env.snapshot()); local.values[name] = cell\n            local._prepared_namespace = namespace; local._class_name = name\n            closure = env.snapshot(); closure.values[name] = cell\n            for label, value in seeded.items():\n                from .objects import ClassMember\n                if type(value) is ClassMember:\n                    stored = install(self, klass, label, value.value, value.contract, value.mutable, value.method, value.capabilities)\n                else: stored = install(self, klass, label, value)\n                local.values[label] = stored\n            pending = {'shell': klass, 'used': False}\n            stack = build_stack(self); stack.append(pending)\n            try:\n                for member in declarations:\n                    original = member[2] if member[0] == 'decorated' else member\n                    label = original[1]\n                    previous = klass.members.get(label)\n                    if previous is not None and label in declared and label not in seeded and not (member[0] == 'decorated' and isinstance(member_value(previous), Property)):\n                        raise LanguageError('类成员不能重名')\n                    if original[0] == 'def':\n                        if member[0] == 'decorated': method = yield from self._s_decorated(member, local, closure)\n                        else:\n                            method = yield from self._s_evaluate(original[2], local)\n                            method.env = closure.snapshot()\n                        owned(method, self)\n                        if previous is not None and label not in seeded and not (isinstance(method, Property) and property_update(method, member_value(previous))):\n                            raise LanguageError('同名属性更新必须继承原 Property')\n                        binds = isinstance(method, Function)\n                        if binds and (not method.params or method.params[0][2] not in ('positional', 'positional_only')):\n                            raise LanguageError('方法需要首个位置接收者参数')\n                        item = create_member(self, method, contract='Function' if binds else 'Any', method=binds)\n                    else:\n                        contract = self.contract(member[2], local)\n                        value = check_type((yield from self._s_evaluate(member[3], local)), contract)\n                        item = create_member(self, value, contract=contract, mutable=member[0]=='var')\n                    effective = yield from namespace_write(self, namespace, label, item)\n                    from .objects import ClassMember\n                    if type(effective) is ClassMember:\n                        stored = install(self, klass, label, effective.value, effective.contract, effective.mutable, effective.method, effective.capabilities)\n                    else: stored = install(self, klass, label, effective)\n                    local.values[label] = stored\n                    seeded.pop(label, None)\n                if original_bases is not None: yield from original_bases_write(self, namespace, original_bases, meta, klass)\n                value = yield from self._s_invoke(meta, [name, bases, namespace], options, synchronous=True)\n                validate_result(self, value)\n                if original_bases is not None: original_bases_result(self, value)\n                from .class_creation import project_value\n                value = project_value(self, value, meta, namespace)\n                cell.value = value\n            finally:\n                if not stack or stack[-1] is not pending: raise LanguageError('类创建上下文失配', code='runtime_error')\n                stack.pop()\n        return env.bind(name, value) if publish else value"}

