TARGETS=tuple(ORIGINALS)

@contextmanager
def reference():
    from chaos import class_creation,metaclasses,language
    from chaos.language import Evaluator
    modules={'class_creation':class_creation,'metaclasses':metaclasses,'language':language}
    reached={name:0 for name in TARGETS}
    replacements=[]
    for key,source in ORIGINALS.items():
        module,name=key.split('.')
        namespace={'__name__':modules[module].__name__,'__package__':'chaos'}
        exec(compile(source,__file__+':original:'+key,'exec'),namespace)
        old=namespace[name]
        # Real module globals preserve late-bound public gateways during callbacks.
        function=FunctionType(old.__code__,vars(modules[module]),name,old.__defaults__,old.__closure__)
        function.__kwdefaults__=old.__kwdefaults__
        def witness(*args,_key=key,_function=function,**kwargs):
            reached[_key]+=1
            return (yield from _function(*args,**kwargs))
        replacements.append((Evaluator if module=='language'else modules[module],name,witness))
    namespace={'__name__':language.__name__,'__package__':'chaos'}
    exec(compile(SUPPORT_EXECUTE,__file__+':original:source_execute','exec'),namespace)
    old=namespace['_s_execute'];execute=FunctionType(old.__code__,vars(language),'_s_execute',old.__defaults__,old.__closure__)
    execute.__kwdefaults__=old.__kwdefaults__
    from chaos.execution_class_creation import ClassSyntaxEvaluationFrame
    with ExitStack()as stack:
        stack.enter_context(patch.object(ClassSyntaxEvaluationFrame,'KINDS',set()))
        for owner,name,value in replacements:stack.enter_context(patch.object(owner,name,value))
        stack.enter_context(patch.object(Evaluator,'_s_execute',execute))
        yield reached
